```typescript
async function fetchData(url: string): Promise<Data | null> {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json() as Data;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error('Failed:', msg);
    return null;
  }
}
```

Generics preserve type information while staying flexible:

```typescript
function identity<T>(value: T): T { return value; }

const num = identity(42);      // type: number
const str = identity('hello'); // type: string

interface Box<T> { value: T; label: string; }
const box: Box<number> = { value: 42, label: 'answer' };
```

```typescript
const [count, setCount] = useState<number>(0);
const [user, setUser] = useState<User | null>(null);
const [items, setItems] = useState<string[]>([]);

// TypeScript also infers from initial value:
const [visible, setVisible] = useState(false); // boolean
```
